using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Fetch a single resource by its unique identifier.")]
    public async Task<string> GetResource(
        [Description("The unique identifier of the resource to retrieve")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching resource {Id}", id);
        var response = await httpClient.GetAsync($"/posts/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("List resources with optional pagination. Returns a JSON array.")]
    public async Task<string> ListResources(
        [Description("Maximum number of items to return (1-100)")] int limit = 10,
        [Description("Number of items to skip for pagination")] int offset = 0,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing resources limit={Limit} offset={Offset}", limit, offset);
        var response = await httpClient.GetAsync(
            $"/posts?_start={offset}&_limit={limit}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool, Description("Create a new resource with the given title and body text.")]
    public async Task<string> CreateResource(
        [Description("Title for the new resource")] string title,
        [Description("Body content of the resource")] string body,
        [Description("Author user ID")] int userId = 1,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating resource titled '{Title}'", title);
        var payload = JsonSerializer.Serialize(new { title, body, userId });
        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");
        var response = await httpClient.PostAsync("/posts", content, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

